<?php if(($room['play_mode']??'sprint')==='paced'): ?><script>
document.addEventListener('DOMContentLoaded',function(){var code=<?= json_encode($room['code']); ?>,uid=<?= (int)$user['id']; ?>,questions=<?= $q_json; ?>,last=-1,sending=false,polling=false,csrfName=<?= json_encode($this->security->get_csrf_token_name()); ?>,csrf=<?= json_encode($this->security->get_csrf_hash()); ?>,stateUrl=<?= json_encode(base_url('belajar/battle/state/'.$room['code'])); ?>,answerUrl=<?= json_encode(base_url('belajar/battle/answer')); ?>,nextUrl=<?= json_encode(base_url('belajar/battle/next')); ?>,moderatorQuestion=-1;
function post(url,data){var b=new URLSearchParams(data);b.append(csrfName,csrf);return fetch(url,{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest','Content-Type':'application/x-www-form-urlencoded'},body:b}).then(function(r){return r.json()})}function safe(v){var d=document.createElement('div');d.textContent=v||'';return d.innerHTML}function show(id){['waiting','monitor','question','done','result'].forEach(function(x){document.getElementById(x).hidden=x!==id})}
function intermission(s,me,earned){var pct=Math.min(100,(s.current_question+1)/questions.length*100);qnum.textContent=s.current_question+1;qtext.textContent='';options.innerHTML='<div class="intermission"><div class="intermission-orb">'+(earned>0?'⚡':'🎯')+'</div><div class="text-secondary text-uppercase fw-bold" style="font-size:.7rem;letter-spacing:.12em">Soal '+(s.current_question+1)+' selesai</div><h2 class="mt-2 mb-2">Siap untuk tantangan berikutnya?</h2><div class="intermission-score"><i class="ti ti-trophy"></i> '+Number(me.score).toLocaleString('id-ID')+' poin · Posisi #'+me.rank+'</div><div class="intermission-track"><span style="width:'+pct+'%"></span></div><p class="muted mb-0">'+(s.current_question+1)+' dari '+questions.length+' soal telah dilalui</p><div class="pulse-dots"><i></i><i></i><i></i></div><small class="text-secondary">Moderator sedang menyiapkan soal berikutnya</small></div>';show('question');last=s.current_question}
function drawQuestion(index){var q=questions[index];if(!q)return;qnum.textContent=index+1;qtext.textContent=q.question;options.innerHTML=q.options.map(function(o,i){return '<button class="opt paced-opt" data-answer="'+i+'"><span class="opt-l">'+['A','B','C','D'][i]+'</span><span>'+safe(o)+'</span></button>'}).join('');show('question');last=index;document.querySelectorAll('.paced-opt').forEach(function(b){b.onclick=function(){if(sending)return;sending=true;document.querySelectorAll('.paced-opt').forEach(function(x){x.disabled=true});post(answerUrl,{code:code,index:index,selected:b.dataset.answer}).then(function(j){if(!j.ok)throw Error(j.message||'Jawaban gagal');var all=document.querySelectorAll('.paced-opt');if(all[j.correct])all[j.correct].classList.add('correct');if(!j.is_correct)b.classList.add('wrong');var msg=document.createElement('div');msg.className='alert '+(j.is_correct?'alert-success':'alert-danger')+' mt-3';msg.innerHTML=j.is_correct?'⚡ Benar! <b>+'+j.points_earned+' poin</b>':'Belum tepat · +0 poin';options.appendChild(msg);setTimeout(function(){fetch(stateUrl+'?_='+Date.now(),{cache:'no-store',headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){return r.json()}).then(function(x){var me=x.state.players.find(function(p){return p.user_id===uid});if(!me)return;if(me.progress<=x.state.current_question)drawQuestion(x.state.current_question);else intermission(x.state,me,j.points_earned)});sending=false},850)}).catch(function(e){sending=false;alert(e.message)})}})}
function renderModerator(s){var current=s.current_question,q=questions[current];if(!q)return;var resultWrap=document.getElementById('operatorResults'),nextBtn=document.getElementById('nextQuestion'),resultBtn=document.getElementById('showOperatorResults');if(moderatorQuestion!==current){moderatorQuestion=current;document.getElementById('operatorQuestionNumber').textContent=current+1;document.getElementById('operatorQuestionText').textContent=q.question;document.getElementById('operatorOptions').innerHTML=q.options.map(function(o,i){return '<div class="operator-option"><span>'+['A','B','C','D'][i]+'</span><b>'+safe(o)+'</b></div>'}).join('');resultWrap.hidden=true;resultBtn.innerHTML='<i class="ti ti-chart-bar me-1"></i>Lihat Hasil Soal '+(current+1)}var answered=s.players.filter(function(p){return p.answered_question!==null&&Number(p.answered_question)===current}).length,pending=Math.max(0,s.players.length-answered);document.getElementById('operatorAnswered').textContent=answered;document.getElementById('operatorPending').textContent=pending;document.getElementById('operatorResponseBar').style.width=(s.players.length?answered/s.players.length*100:0)+'%';nextBtn.querySelector('span').textContent=current>=questions.length-1?'Akhiri Battle & Tampilkan Juara':'Buka Soal '+(current+2);document.getElementById('operatorHint').textContent='Soal aktif '+(current+1)+' dari '+questions.length}function apply(s){if(s.status!=='playing'||s.play_mode!=='paced')return;var me=s.players.find(function(p){return p.user_id===uid});if(<?= $is_moderator?'true':'false'; ?>){renderModerator(s);show('monitor');return}if(!me)return;if(me.progress>s.current_question){if(last!==s.current_question||!options.querySelector('.intermission'))intermission(s,me,0);return}if(last!==s.current_question||options.querySelector('.intermission'))drawQuestion(s.current_question)}
function poll(){if(polling)return;polling=true;fetch(stateUrl+'?_='+Date.now(),{cache:'no-store',headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){return r.json()}).then(function(j){if(j.ok)apply(j.state)}).catch(function(){}).finally(function(){polling=false})}var reveal=document.getElementById('showOperatorResults'),next=document.getElementById('nextQuestion');if(reveal)reveal.onclick=function(){document.getElementById('operatorResults').hidden=false;reveal.innerHTML='<i class="ti ti-eye-off me-1"></i>Sembunyikan Hasil';reveal.onclick=function(){var wrap=document.getElementById('operatorResults'),hidden=!wrap.hidden;wrap.hidden=hidden;reveal.innerHTML=hidden?'<i class="ti ti-chart-bar me-1"></i>Lihat Hasil Kumulatif':'<i class="ti ti-eye-off me-1"></i>Sembunyikan Hasil'}};if(next)next.onclick=function(){next.disabled=true;post(nextUrl,{code:code}).then(function(j){if(!j.ok)throw Error(j.message||'Gagal');last=-1;moderatorQuestion=-1;document.getElementById('operatorResults').hidden=true;poll()}).catch(function(e){alert(e.message)}).finally(function(){next.disabled=false})};setInterval(poll,350);poll()});
</script><?php endif; ?>
<style>
.players{perspective:900px}.player{position:relative;overflow:hidden;transition:transform .35s,box-shadow .35s,outline-color .35s}.player::after{content:'';position:absolute;inset:0;background:linear-gradient(115deg,transparent 25%,#fff8 48%,transparent 70%);transform:translateX(-130%)}.player.leader{background:linear-gradient(135deg,#fffbeb,#fff7d6);box-shadow:0 9px 28px #f59e0b33;transform:translateY(-4px)}.player.leader::after{animation:shine 2.4s infinite}.player.rank-up{animation:rankUp .55s ease}.player .live-meta{display:flex;justify-content:space-between;color:#64748b;font-size:.7rem;margin-top:5px}.rank{position:relative;align-items:center;border:1px solid #ede9fe!important;border-radius:14px;margin:8px 0;background:#fff;box-shadow:0 4px 14px #312e8110;transition:transform .3s}.rank:first-child{background:linear-gradient(120deg,#fff8d7,#fff);border-color:#facc15!important;box-shadow:0 8px 24px #eab30826}.rank-medal{font-size:1.35rem}.rank-time{font-size:.74rem;color:#64748b;display:block;margin-top:2px}.rank-score{font-size:1.05rem;color:#6d28d9}.guest-tag{font-size:.62rem;padding:2px 6px;border-radius:99px;background:#e0f2fe;color:#0369a1;margin-left:5px}.battle-confetti{position:fixed;top:-20px;z-index:9999;pointer-events:none;animation:confettiFall 2.8s linear forwards}@keyframes shine{55%,100%{transform:translateX(130%)}}@keyframes rankUp{50%{transform:translateY(-10px) scale(1.03)}}@keyframes confettiFall{to{transform:translate(var(--drift),105vh) rotate(720deg);opacity:.2}}
.player-user,.rank-user{display:block;color:#7c3aed;font-size:.7rem;font-weight:700;margin-top:1px}.me-tag{font-size:.6rem;background:#7c3aed;color:#fff;border-radius:99px;padding:2px 6px;margin-left:5px}.intermission{padding:12px 4px}.intermission-orb{width:76px;height:76px;margin:2px auto 16px;border-radius:24px;display:grid;place-items:center;font-size:2rem;background:linear-gradient(135deg,#ede9fe,#cffafe);box-shadow:0 10px 28px #7c3aed24;animation:floatSoft 2.6s ease-in-out infinite}.intermission-score{display:inline-flex;align-items:center;gap:8px;background:#f5f3ff;color:#6d28d9;border-radius:99px;padding:8px 15px;font-weight:800}.intermission-track{height:8px;border-radius:20px;background:#ede9fe;overflow:hidden;margin:18px auto 8px;max-width:390px}.intermission-track span{display:block;height:100%;background:linear-gradient(90deg,#8b5cf6,#06b6d4);transition:width .4s}.pulse-dots{display:flex;justify-content:center;gap:6px;margin-top:18px}.pulse-dots i{width:7px;height:7px;border-radius:50%;background:#8b5cf6;animation:dotSoft 1.4s ease-in-out infinite}.pulse-dots i:nth-child(2){animation-delay:.18s}.pulse-dots i:nth-child(3){animation-delay:.36s}@keyframes floatSoft{50%{transform:translateY(-5px)}}@keyframes dotSoft{0%,60%,100%{opacity:.25;transform:scale(.8)}30%{opacity:1;transform:scale(1.15)}}
</style>
<script>
(function(){var previous={},celebrated=false,lastCards='',lastBoard='',url=<?= json_encode(base_url('belajar/battle/state/'.$room['code'])); ?>,total=<?= count($questions); ?>,paced=<?= ($room['play_mode']??'sprint')==='paced'?'true':'false'; ?>;
function esc(v){var d=document.createElement('div');d.textContent=v||'';return d.innerHTML}function duration(v){if(v===null||v===undefined)return 'Masih bertanding';var m=Math.floor(v/60),s=v-m*60;return String(m).padStart(2,'0')+':'+s.toFixed(3).padStart(6,'0')}function scoreText(p){return paced?p.score.toLocaleString('id-ID')+' poin':p.score+'/'+total}function leaderboard(ps){return ps.map(function(p,i){var medal=['🥇','🥈','🥉'][i]||'#'+(i+1),me=p.user_id===<?= (int)$user['id']; ?>;return '<div class="rank"><span class="rank-medal">'+medal+'</span><span><b>'+esc(p.name)+'</b>'+(me?'<span class="me-tag">KAMU</span>':'')+(p.is_guest?'<span class="guest-tag">TAMU</span>':'')+'<small class="rank-user">@'+esc(p.username)+'</small><small class="rank-time"><i class="ti ti-stopwatch"></i> '+duration(p.elapsed_seconds)+'</small></span><span class="rank-score"><b>'+scoreText(p)+'</b></span></div>'}).join('')}
function confetti(){if(celebrated)return;celebrated=true;for(var i=0;i<55;i++){var x=document.createElement('i');x.className='battle-confetti';x.style.left=Math.random()*100+'vw';x.style.width=x.style.height=(5+Math.random()*8)+'px';x.style.background=['#f59e0b','#ec4899','#8b5cf6','#22c55e','#06b6d4'][i%5];x.style.setProperty('--drift',(Math.random()*180-90)+'px');x.style.animationDelay=Math.random()*.7+'s';document.body.appendChild(x);setTimeout(function(n){n.remove()},3600,x)}}
function paint(s){if(s.status==='waiting')return;var cards=document.getElementById('players'),cardHtml=s.players.map(function(p,i){var moved=previous[p.id]!==undefined&&previous[p.id]>i+1,me=p.user_id===<?= (int)$user['id']; ?>;previous[p.id]=i+1;return '<div class="player '+(i===0?'leader ':'')+(moved?'rank-up ':'')+(me?'me':'')+'"><div class="nm">'+(['🥇','🥈','🥉'][i]||'#'+(i+1))+' '+esc(p.name)+(me?'<span class="me-tag">KAMU</span>':'')+(p.is_guest?'<span class="guest-tag">TAMU</span>':'')+'<small class="player-user">@'+esc(p.username)+'</small></div><div class="sc">'+scoreText(p)+'</div><div class="pbar"><div style="width:'+(p.progress/total*100)+'%"></div></div><div class="live-meta"><span>'+p.progress+'/'+total+' soal</span><span>'+duration(p.elapsed_seconds)+'</span></div></div>'}).join('');if(cards&&cardHtml!==lastCards){cards.innerHTML=cardHtml;lastCards=cardHtml}var html=leaderboard(s.players),live=document.getElementById('liveRanking'),final=document.getElementById('ranking');if(live&&html!==lastBoard){live.innerHTML=html;lastBoard=html}if(s.status==='finished'&&final&&html!==final.dataset.snapshot){final.innerHTML=html;final.dataset.snapshot=html;confetti()}}
function refresh(){fetch(url+'?_='+Date.now(),{cache:'no-store',headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){return r.json()}).then(function(j){if(j.ok)paint(j.state)}).catch(function(){})}setInterval(refresh,900);refresh()})();
</script>
<style>.operator-head{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.operator-question{text-align:left;padding:18px;border:1px solid #e7e3f5;border-radius:16px;background:linear-gradient(135deg,#faf7ff,#fff)}.operator-option{display:flex;align-items:center;gap:11px;padding:11px 13px;margin-top:8px;border:1px solid #e2e8f0;border-radius:12px;background:#fff}.operator-option span{display:grid;place-items:center;flex:none;width:28px;height:28px;border-radius:9px;background:#ede9fe;color:#6d28d9;font-weight:900}.operator-status{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:15px 0 9px}.operator-stat{padding:12px;border-radius:13px;background:#f8fafc}.operator-stat strong{display:block;font-size:1.45rem}.operator-track{height:8px;overflow:hidden;border-radius:99px;background:#e5e7eb;margin-bottom:14px}.operator-track span{display:block;height:100%;background:linear-gradient(90deg,#8b5cf6,#06b6d4);transition:width .35s}.operator-results{margin-top:15px;padding-top:14px;border-top:1px solid #eee}.operator-results[hidden]{display:none!important}@media(max-width:575px){.operator-status{grid-template-columns:1fr}.panel{padding:18px}}</style><div class="panel" id="monitor" hidden><div class="operator-head"><div class="text-start"><div class="muted">Moderator · Soal <span id="operatorQuestionNumber">1</span> dari <?= count($questions); ?></div><h3 class="mb-0">Panduan Soal Aktif</h3></div><span class="badge bg-purple-lt">LIVE</span></div><div class="operator-question"><div class="qtext mt-0" id="operatorQuestionText"></div><div id="operatorOptions"></div></div><button id="showOperatorResults" class="btn btn-outline-primary w-100 mt-3"><i class="ti ti-chart-bar me-1"></i>Lihat Hasil</button><div class="operator-status"><div class="operator-stat"><span class="muted">Sudah menjawab</span><strong class="text-green" id="operatorAnswered">0</strong></div><div class="operator-stat"><span class="muted">Belum menjawab</span><strong class="text-orange" id="operatorPending">0</strong></div></div><div class="operator-track"><span id="operatorResponseBar" style="width:0"></span></div><div class="operator-results" id="operatorResults" hidden><h3>Ranking Kumulatif</h3><p class="muted">Total poin sampai soal ini.</p><div class="ranking" id="liveRanking"></div></div><?php if($is_moderator&&($room['play_mode']??'sprint')==='paced'): ?><button id="nextQuestion" class="btn btn-primary w-100 mt-3"><i class="ti ti-player-track-next"></i> <span>Buka Soal Berikutnya</span></button><small id="operatorHint" class="d-block text-secondary mt-2"></small><?php endif; ?></div><div class="panel" id="question" hidden><div class="muted">Soal <span id="qnum">1</span> dari <?= count($questions); ?></div><div class="qtext" id="qtext"></div><div id="options"></div></div><div class="panel" id="done" hidden><div style="font-size:3rem">✅</div><h3>Kamu sudah selesai!</h3><p class="muted">Waktu selesai sudah tercatat. Menunggu pemain lain…</p><div class="spin"></div></div><div class="panel" id="result" hidden><div style="font-size:3.4rem" id="emoji">🏆</div><h2 id="title">Hasil Battle</h2><p class="muted"><?= ($room['play_mode']??'sprint')==='paced'?'Peringkat berdasarkan total poin akurasi dan kecepatan setiap soal.':'Peringkat ditentukan dari skor, lalu waktu selesai.'; ?></p><div class="ranking" id="ranking"></div><div class="d-flex gap-2"><a href="<?= base_url('belajar/battle'); ?>" class="btn btn-outline-primary flex-fill">Main Lagi</a><a href="<?= base_url('belajar'); ?>" class="btn btn-primary flex-fill">Arena Belajar</a></div></div></div>
<script>(function(){'use strict';var CODE=<?= json_encode($room['code']); ?>,UID=<?= (int)$user['id']; ?>,MODERATOR=<?= $is_moderator?'true':'false'; ?>,QS=<?= $q_json; ?>,N=QS.length,progress=<?= (int)$participant['progress']; ?>,finished=<?= !empty($participant['finished'])?'true':'false'; ?>,busy=false,resultShown=false,waitingSnapshot='',csrfName=<?= json_encode($this->security->get_csrf_token_name()); ?>,csrf=<?= json_encode($this->security->get_csrf_hash()); ?>;var ids=['waiting','monitor','question','done','result'];function show(x){ids.forEach(function(id){document.getElementById(id).hidden=id!==x;});}function post(url,data){var b=new URLSearchParams(data);b.append(csrfName,csrf);return fetch(url,{method:'POST',headers:{'X-Requested-With':'XMLHttpRequest','Content-Type':'application/x-www-form-urlencoded'},body:b}).then(function(r){return r.json();});}function esc(s){var d=document.createElement('div');d.textContent=s||'';return d.innerHTML;}function renderQ(){if(progress>=N){finished=true;show('done');return;}var q=QS[progress];qnum.textContent=progress+1;qtext.textContent=q.question;options.innerHTML='';q.options.forEach(function(o,i){var b=document.createElement('button');b.className='opt';b.innerHTML='<span class="opt-l">'+['A','B','C','D'][i]+'</span><span>'+esc(o)+'</span>';b.onclick=function(){answer(i);};options.appendChild(b);});show('question');}function answer(i){if(busy)return;busy=true;document.querySelectorAll('.opt').forEach(function(x){x.disabled=true;});post(<?= json_encode(base_url('belajar/battle/answer')); ?>,{code:CODE,index:progress,selected:i}).then(function(j){if(!j.ok)throw Error(j.message||'Gagal');if(j.ignored){progress=j.progress;busy=false;renderQ();return;}var os=document.querySelectorAll('.opt');if(os[j.correct])os[j.correct].classList.add('correct');if(!j.is_correct&&os[i])os[i].classList.add('wrong');setTimeout(function(){progress=j.progress;finished=j.finished;busy=false;j.finished?show('done'):renderQ();poll();},650);}).catch(function(e){busy=false;alert(e.message);document.querySelectorAll('.opt').forEach(function(x){x.disabled=false;});});}function apply(s){var minimum=Number(s.minimum_players||2),rosterHtml=s.players.map(function(p){return '<span class="chip">'+esc(p.name)+(p.is_host?' · Host':'')+'</span>';}).join(''),snapshot=rosterHtml+'|'+s.players.length+'|'+s.max_players+'|'+minimum;if(s.status==='waiting'&&snapshot!==waitingSnapshot){roster.innerHTML=rosterHtml;capacity.textContent=(s.max_players===null?s.players.length+' pemain · tanpa batas':s.players.length+' / '+s.max_players+' pemain')+(s.players.length<minimum?' · minimal '+minimum+' untuk mulai':' · siap dimulai');waitingSnapshot=snapshot}var sb=document.getElementById('start');if(sb)sb.disabled=s.players.length<minimum;if(s.status==='finished'){showResult(s);return;}if(s.status==='waiting'){show('waiting');return;}if(MODERATOR){show('monitor');return;}var me=s.players.find(function(p){return p.user_id===UID;});if(me){progress=me.progress;finished=me.finished;}if(finished)show('done');else if(document.getElementById('question').hidden)renderQ();}function showResult(s){if(resultShown)return;resultShown=true;var won=s.winner_user_id===UID&&!MODERATOR;emoji.textContent=won?'🏆':'👏';title.textContent=won?'Kamu Juara!':'Battle Selesai';show('result');}function poll(){fetch(<?= json_encode(base_url('belajar/battle/state/')); ?>+CODE+'?_='+Date.now(),{cache:'no-store',headers:{'X-Requested-With':'XMLHttpRequest'}}).then(function(r){return r.json();}).then(function(j){if(j.ok)apply(j.state);});}var start=document.getElementById('start');if(start)start.onclick=function(){start.disabled=true;post(<?= json_encode(base_url('belajar/battle/start')); ?>,{code:CODE}).then(function(j){if(!j.ok)throw Error(j.message);poll();}).catch(function(e){alert(e.message);start.disabled=false;});};poll();setInterval(poll,1200);})();</script></body></html>
